"""PHP · Etapa 5: seguridad, interoperabilidad y PHP moderno."""
from ..generador import K

LISTA = [
K("Seguridad y datos", d="prácticas para validar y manejar datos sin confiar ciegamente en ellos", u="reducir errores al procesar valores de distintas fuentes", mas="Los datos deben validarse según el uso esperado y codificarse al mostrarlos en un contexto concreto. La validación no sustituye la parametrización de consultas ni el escape de salida.", k=["Los datos externos deben validarse antes de usarlos.", "La validación comprueba si un valor cumple una regla esperada.", "Escapar datos de salida depende del contexto donde se muestran."], sit="Un valor de entrada debe cumplir un formato antes de ser aceptado; ¿qué práctica de seguridad aplicas?", cod="<?php $edad = '21'; echo ctype_digit($edad) ? 'válida' : 'inválida';", h="valida que una cadena contenga solo dígitos", pr=("Comprobar que un dato cumple un formato esperado es ___.", "validación"), ec="confiar en un valor solo porque llegó desde un formulario", pr2=("La cadena numérica del ejemplo es ___.", "válida"), out="válida"),
K("Sesiones y frameworks", d="mecanismos del ecosistema PHP para mantener estado y estructurar aplicaciones", u="organizar el estado del usuario y el código de una aplicación", mas="Una sesión permite asociar estado entre solicitudes mediante identificadores gestionados por PHP; los frameworks ofrecen convenciones y componentes para aplicaciones. Este ejemplo usa un arreglo local para no iniciar una sesión ni acceder a servicios externos.", k=["Las sesiones permiten conservar estado entre solicitudes.", "Los frameworks aportan convenciones y componentes reutilizables.", "El estado real de sesión no se obtiene de un arreglo local ordinario."], sit="Quieres aprender a leer una clave de estado sin depender de una solicitud web real; ¿qué práctica local haces primero?", cod="<?php $estado = ['tema' => 'claro']; echo $estado['tema'];", h="consulta una clave de estado modelada en un arreglo local", pr=("Un conjunto de herramientas y convenciones para una aplicación se denomina ___.", "framework"), ec="suponer que un arreglo local inicia o conserva automáticamente una sesión web", pr2=("El tema elegido en el ejemplo es ___.", "claro"), out="claro"),
K("Escape HTML", d="codificación de caracteres especiales para mostrarlos como texto en HTML", u="evitar que datos de texto se interpreten como marcado", mas="htmlspecialchars convierte caracteres como < y > en entidades HTML. Para contenido UTF-8 se recomienda indicar la codificación; la codificación debe realizarse al generar la salida, según el contexto.", k=["htmlspecialchars codifica caracteres especiales de HTML.", "Escapar salida ayuda a impedir que texto se interprete como marcado.", "La codificación de salida no reemplaza validar los datos."], sit="Un texto debe aparecer como contenido literal y no convertirse en etiquetas del navegador; ¿qué función aplicas?", cod="<?php echo htmlspecialchars('<b>', ENT_QUOTES, 'UTF-8');", h="convierte los signos de menor y mayor en entidades HTML", pr=("La función PHP que codifica caracteres especiales HTML es ___.", "htmlspecialchars"), ec="imprimir texto no confiable como HTML sin codificarlo", pr2=("El signo menor que se convierte en la entidad ___.", "&lt;"), out="&lt;b&gt;"),
K("Validación con filter_var", d="comprobación de un valor usando un filtro definido por PHP", u="validar formatos comunes con filtros incorporados", mas="filter_var aplica un filtro como FILTER_VALIDATE_EMAIL y devuelve el valor validado o false. La validación de sintaxis no confirma por sí sola que una dirección exista o pertenezca a una persona.", k=["FILTER_VALIDATE_EMAIL comprueba la sintaxis básica de correo.", "filter_var puede devolver false si la validación falla.", "La validación sintáctica no demuestra que un correo exista."], sit="Debes comprobar el formato de una dirección sin enviar un mensaje de verificación; ¿qué filtro usas?", cod="<?php $correo = 'ana@example.com'; echo filter_var($correo, FILTER_VALIDATE_EMAIL) ? 'válido' : 'no';", h="valida la sintaxis del correo sin realizar una conexión", pr=("El filtro de PHP para validar formato de correo es ___.", "FILTER_VALIDATE_EMAIL"), ec="interpretar una validación de sintaxis como prueba de que el buzón existe", pr2=("La dirección del ejemplo tiene formato ___ .", "válido"), out="válido"),
K("Marcadores SQL", d="parámetros separados del texto SQL para representar datos de consulta", u="preparar consultas sin concatenar entradas en el SQL", mas="Las consultas preparadas usan marcadores para separar la estructura SQL de los valores. PDO puede enlazar parámetros al ejecutar una consulta; el ejemplo solo construye texto local y no conecta con una base de datos.", k=["Un marcador representa un dato en una consulta preparada.", "Los valores se enlazan separadamente de la estructura SQL.", "Concatenar directamente entradas en SQL puede permitir inyección."], sit="Una consulta debe identificar un valor sin incrustar texto recibido en su estructura; ¿qué recurso SQL empleas?", cod="<?php $sql = 'SELECT nombre FROM persona WHERE id = :id'; echo str_contains($sql, ':id') ? 'marcador' : 'falta';", h="comprueba en texto local que la consulta tiene un marcador nombrado", pr=("El parámetro que sustituye un dato en una consulta preparada es un ___.", "marcador"), ec="concatenar directamente una entrada dentro del SQL", pr2=("La consulta contiene el marcador ___.", ":id"), out="marcador"),
K("Comparación segura de cadenas", d="función hash_equals que compara cadenas con protección frente a filtraciones temporales", u="comparar valores secretos de longitud conocida con una función adecuada", mas="hash_equals se diseñó para comparar cadenas sin exponer de forma simple el tiempo de comparación según el prefijo coincidente. Se pasa primero el valor conocido y luego el valor recibido.", k=["hash_equals compara dos cadenas.", "La función ayuda a evitar ataques de temporización en comparaciones de secretos.", "El argumento conocido debe pasarse primero."], sit="Una comprobación compara un token local con una cadena esperada sin usar una comparación ordinaria; ¿qué función eliges?", cod="<?php var_export(hash_equals('abc123', 'abc123'));", h="compara dos cadenas iguales con hash_equals", pr=("La función PHP para comparar cadenas de forma segura es ___.", "hash_equals"), ec="revelar diferencias de secreto usando una comparación manual carácter por carácter", pr2=("Las dos cadenas iguales producen ___.", "true"), out="true"),
K("Codificar JSON", d="transformación de valores PHP compatibles a una cadena JSON", u="representar datos estructurados en formato JSON", mas="json_encode convierte valores compatibles como arreglos y escalares en una cadena JSON. Las opciones permiten controlar detalles de codificación; el resultado del ejemplo es determinista.", k=["json_encode produce una cadena JSON o false en caso de error.", "Los arreglos asociativos se codifican como objetos JSON.", "JSON_UNESCAPED_UNICODE conserva caracteres Unicode legibles en la salida."], sit="Necesitas representar una estructura local como texto JSON para otro componente; ¿qué función llamas?", cod="<?php echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE);", h="convierte un arreglo asociativo a una cadena JSON", pr=("La función que serializa datos PHP a JSON es ___.", "json_encode"), ec="confundir el arreglo PHP original con la cadena JSON producida", pr2=("La salida codificada representa un objeto con ok igual a ___.", "true"), out="{\"ok\":true}"),
K("Decodificar JSON", d="transformación de una cadena JSON a valores PHP", u="leer datos JSON ya disponibles en memoria", mas="json_decode analiza una cadena JSON. Por defecto convierte objetos JSON en objetos stdClass; al pasar true como segundo argumento, los objetos se convierten en arreglos asociativos.", k=["json_decode analiza una cadena JSON.", "El segundo argumento true solicita arreglos asociativos.", "Una cadena JSON inválida produce null por defecto."], sit="Una cadena JSON local debe convertirse a arreglo asociativo sin leer un archivo; ¿qué función usas?", cod="<?php $d = json_decode('{\"n\":4}', true); echo $d['n'];", h="decodifica un objeto JSON en arreglo y lee su campo", pr=("La función que analiza una cadena JSON es ___.", "json_decode"), ec="tratar el resultado predeterminado como arreglo sin pedir modo asociativo", pr2=("El valor decodificado de n es ___.", "4"), out="4"),
K("Generadores", d="funciones que producen una secuencia de valores al usar yield", u="recorrer valores generados sin construir una lista completa", mas="Al ejecutar yield dentro de una función, esta se convierte en generador y produce valores al iterarse. La ejecución se pausa en cada yield y continúa al pedir el siguiente elemento.", k=["yield produce un valor de un generador.", "Una función generadora devuelve un objeto Generator al invocarse.", "El generador pausa y reanuda su ejecución durante la iteración."], sit="Una secuencia de resultados debe producirse elemento por elemento sin crear primero un arreglo; ¿qué mecanismo usas?", cod="<?php function pares() { yield 2; yield 4; } foreach (pares() as $n) { echo $n; }", h="produce dos valores y los recorre", pr=("La palabra clave que emite un valor en un generador es ___.", "yield"), ec="esperar que yield retorne un arreglo completo de inmediato", pr2=("El segundo valor generado es ___.", "4"), out="24"),
K("Delegar con yield from", d="sintaxis que delega la producción de valores a otro iterable", u="componer generadores y secuencias existentes", mas="yield from recorre y delega los valores de un iterable desde un generador. Permite combinar secuencias sin escribir manualmente un bucle intermedio.", k=["yield from delega valores de un iterable.", "Se puede usar dentro de una función generadora.", "La delegación conserva el orden del iterable recorrido."], sit="Un generador debe incluir en orden los elementos de otro iterable; ¿qué instrucción de delegación aplicas?", cod="<?php function letras() { yield from ['a', 'b']; } foreach (letras() as $l) { echo $l; }", h="delega a un arreglo la producción de letras", pr=("La forma de delegar un iterable en un generador es ___.", "yield from"), ec="usar yield from fuera de una función generadora", pr2=("La segunda letra producida es ___.", "b"), out="ab"),
K("Callable de primera clase", d="sintaxis ...función que obtiene un objeto callable desde una función existente", u="pasar una función como valor sin envolverla en una clausura", mas="PHP 8.1 permite crear un callable de primera clase con la sintaxis nombre(...). El operador de elipsis aparece vacío y el resultado se puede invocar o pasar a otra función.", k=["La sintaxis nombre(...) crea un callable de primera clase.", "Los callables de primera clase están disponibles desde PHP 8.1.", "El resultado puede guardarse e invocarse como una función."], sit="Necesitas guardar la función existente strlen en una variable callable sin crear una clausura manual; ¿qué sintaxis usas?", cod="<?php $f = strlen(...); echo $f('PHP');", h="crea y ejecuta un callable de primera clase", pr=("La sintaxis para crear un callable de primera clase termina en ___.", "..."), ec="confundir strlen(...) como callable con llamar strlen sin argumentos", pr2=("La longitud de PHP es ___.", "3"), out="3"),
K("Operador nullsafe", d="operador ?-> que omite el acceso cuando el valor de la izquierda es null", u="encadenar accesos opcionales sin comprobaciones repetidas", mas="El operador nullsafe, disponible desde PHP 8.0, devuelve null si el operando izquierdo de ese acceso es null. Si no lo es, realiza el acceso; el operador puede encadenarse.", k=["?-> es el operador de acceso nullsafe.", "Si el operando izquierdo es null, el acceso devuelve null.", "El operador nullsafe no permite asignar a través del acceso."], sit="Una referencia opcional puede faltar y no quieres dereferenciar null al leer su campo; ¿qué operador aplicas?", cod="<?php $persona = null; var_export($persona?->nombre);", h="devuelve null sin intentar leer una propiedad inexistente", pr=("El operador PHP de acceso seguro ante null es ___.", "?->"), ec="intentar asignar una propiedad mediante el operador nullsafe", pr2=("El resultado al acceder desde null es ___.", "NULL"), out="NULL"),
K("Atributos", d="metadatos declarativos que se escriben como #[...] sobre declaraciones", u="asociar información estructurada a clases, métodos o parámetros", mas="Los atributos se introdujeron en PHP 8. Se pueden leer mediante Reflection; una clase de atributo se marca con #[Attribute] cuando se quiere restringir su uso.", k=["Los atributos comienzan con #[.]", "Los atributos se pueden aplicar a declaraciones permitidas.", "Reflection permite inspeccionar atributos durante la ejecución."], sit="Una clase necesita metadatos declarativos consultables con Reflection sin ejecutar lógica de entrada; ¿qué característica de PHP 8 usas?", cod="<?php #[Attribute] class Marca {} #[Marca] class Informe {} echo count((new ReflectionClass(Informe::class))->getAttributes());", h="inspecciona un atributo aplicado a una clase", pr=("Los metadatos declarativos de PHP 8 empiezan con ___.", "#["), ec="tratar un atributo como comentario sin consultar Reflection cuando se necesitan sus datos", pr2=("La clase Informe tiene ___ atributo.", "1"), out="1"),
K("Tipos de intersección", d="tipo que exige que un valor cumpla simultáneamente varios contratos", u="restringir un argumento a objetos con capacidades combinadas", mas="Un tipo de intersección usa & entre nombres de interfaces o clases compatibles. PHP 8.1 lo admite para declarar que un valor debe satisfacer todos los tipos indicados.", k=["A&B significa que el valor debe cumplir ambos tipos.", "Los tipos de intersección se introdujeron en PHP 8.1.", "Los miembros de una intersección deben ser tipos que puedan coexistir."], sit="Un argumento debe satisfacer simultáneamente dos interfaces; ¿qué declaración de tipo expresa el requisito?", cod="<?php interface A {} interface B {} class X implements A, B {} function usar(A&B $x): string { return 'ok'; } echo usar(new X());", h="pasa un objeto que implementa ambos contratos requeridos", pr=("El símbolo que combina requisitos simultáneos de tipo es ___.", "&"), ec="usar | cuando ambos contratos son obligatorios", pr2=("El objeto que cumple ambos contratos produce ___.", "ok"), out="ok"),
K("Clases readonly", d="clases cuyos campos de instancia declarados son readonly", u="modelar objetos inmutables después de su inicialización", mas="PHP 8.2 añadió la declaración readonly class. Sus propiedades declaradas deben ser readonly y la clase no puede agregar propiedades dinámicas; el estado debe inicializarse de forma controlada.", k=["readonly class se incorporó en PHP 8.2.", "Las propiedades declaradas en una clase readonly son readonly.", "Una clase readonly no admite propiedades dinámicas."], sit="Una entidad debe impedir cambios a su estado luego de construirse; ¿qué declaración de clase ofrece PHP 8.2?", cod="<?php readonly class Color { public function __construct(public string $nombre) {} } echo (new Color('azul'))->nombre;", h="crea una instancia de clase readonly y lee su dato", pr=("La declaración PHP 8.2 de clase inmutable empieza con ___.", "readonly class"), ec="intentar cambiar una propiedad de una clase readonly tras inicializarla", pr2=("El nombre del color inmutable es ___.", "azul"), out="azul"),
K("Fibras", d="objetos Fiber que permiten suspender y reanudar una ejecución cooperativa", u="representar pausas explícitas en flujos cooperativos", mas="Las fibras se añadieron en PHP 8.1 y ofrecen suspensión explícita de una pila de ejecución. No crean paralelismo por sí solas; una función puede ceder el control con Fiber::suspend y reanudarse después.", k=["Fiber se incorporó en PHP 8.1.", "Fiber::suspend pausa la fibra y puede devolver un valor al iniciador.", "Las fibras no son ejecución paralela automática."], sit="Una tarea debe pausar explícitamente y devolver el control a su iniciador sin crear otro proceso; ¿qué abstracción moderna representa esa pausa?", cod="<?php $f = new Fiber(fn() => Fiber::suspend('pausa')); echo $f->start();", h="inicia una fibra que suspende y entrega un valor", pr=("La abstracción cooperativa introducida en PHP 8.1 se llama ___.", "Fiber"), ec="confundir una pausa cooperativa con paralelismo simultáneo", pr2=("El valor de suspensión emitido es ___.", "pausa"), out="pausa"),
K("Clonación", d="operación clone que crea una copia superficial de un objeto", u="duplicar un objeto para cambiar una instancia por separado", mas="clone crea una copia superficial: los escalares se copian, pero las propiedades que contienen otros objetos siguen apuntando a esos objetos. El método __clone permite personalizar el proceso.", k=["clone crea un nuevo objeto del mismo tipo.", "La clonación predeterminada es superficial.", "__clone puede personalizar el objeto recién clonado."], sit="Necesitas un segundo objeto del mismo tipo con su propio valor escalar inicial; ¿qué operador aplicas?", cod="<?php class Nota { public int $n = 2; } $a = new Nota(); $b = clone $a; $b->n = 5; echo $a->n, $b->n;", h="clona una instancia y modifica el escalar de la copia", pr=("El operador que copia un objeto es ___.", "clone"), ec="suponer que clone duplica recursivamente todos los objetos anidados", pr2=("Los valores originales y copiados aparecen como ___.", "25"), out="25"),
K("Método mágico __toString", d="método que define la representación textual de un objeto", u="controlar el texto producido al convertir un objeto en cadena", mas="__toString debe devolver una cadena y permite definir la conversión textual de un objeto. En PHP moderno, lanzar una excepción desde __toString está permitido desde PHP 7.4.", k=["__toString define la conversión de un objeto a texto.", "__toString debe devolver un string.", "El método se invoca al usar el objeto donde se necesita una cadena."], sit="Un objeto debe producir una etiqueta legible al interpolarlo como texto; ¿qué método mágico implementas?", cod="<?php class Etiqueta { public function __toString(): string { return 'PHP'; } } echo new Etiqueta();", h="convierte automáticamente una instancia a su texto definido", pr=("El método mágico para convertir un objeto a cadena es ___.", "__toString"), ec="devolver un valor que no sea string desde __toString", pr2=("La representación textual del objeto es ___.", "PHP"), out="PHP"),
K("str_contains", d="función que comprueba si una cadena contiene otra cadena", u="buscar una subcadena sin usar expresiones regulares", mas="str_contains está disponible desde PHP 8.0 y devuelve bool. La búsqueda distingue mayúsculas de minúsculas y una cadena buscada vacía se considera contenida.", k=["str_contains devuelve true o false.", "La búsqueda de str_contains distingue mayúsculas de minúsculas.", "str_contains se añadió en PHP 8.0."], sit="Quieres comprobar de forma directa si una etiqueta incluye un fragmento textual; ¿qué función de PHP 8 invocas?", cod="<?php var_export(str_contains('php 8', '8'));", h="comprueba que el texto buscado aparece dentro de la cadena", pr=("La función de PHP 8 para verificar que un texto contiene otro es ___.", "str_contains"), ec="esperar que str_contains ignore mayúsculas y minúsculas", pr2=("La cadena sí incluye el carácter buscado: ___.", "true"), out="true"),
K("Errores de JSON", d="manejo de fallos de análisis JSON mediante excepciones", u="distinguir un documento inválido de un valor JSON null", mas="json_decode normalmente devuelve null tanto para el valor JSON null como ante ciertos errores. JSON_THROW_ON_ERROR, disponible desde PHP 7.3, hace que los errores de análisis lancen JsonException.", k=["json_decode puede devolver null para un JSON inválido.", "JSON_THROW_ON_ERROR convierte errores de análisis en JsonException.", "El valor JSON null también se decodifica como null sin lanzar excepción."], sit="Un analizador debe distinguir una entrada mal formada del valor JSON null; ¿qué opción de decodificación habilitas?", cod="<?php try { json_decode('{', false, 512, JSON_THROW_ON_ERROR); } catch (JsonException $e) { echo 'error'; }", h="captura el error producido al analizar JSON inválido", pr=("La opción que hace que JSON arroje excepciones es ___.", "JSON_THROW_ON_ERROR"), ec="interpretar null como prueba inequívoca de que no hubo error de JSON", pr2=("El JSON inválido se informa como un ___ .", "error"), out="error"),
]
